from collections import defaultdict

def attach_readings(sensors, latest):
    readings = defaultdict(dict)
    for sensor_id, sensor in sensors.items():
        if sensor_id not in readings:
            readings[sensor_id] = {}
        if sensor.get("latest") is not None:
            readings[sensor_id][sensor_id] = sensor.get("latest")
        else:
            readings[sensor_id][sensor_id] = None
    return {sensor_id: {sensor_id: reading} for sensor_id, reading in readings.items() if reading}

