def coerce_field(value):
    if value is None:
        return None
    elif isinstance(value, bool):
        return "true" if value else "false"
    elif isinstance(value, str):
        return value.strip()
    elif isinstance(value, (int, float)):
        return str(value)
    else:
        raise TypeError(f"unsupported type {type(value)}")

from itertools import accumulate

def total_coverage(spans):
    if not spans:
        return 0
    sorted_spans = sorted(spans, key=lambda x: x[0])
    return sum(accumulate([span[1] - span[0] for span in sorted_spans[1:]]))

from datetime import datetime

def ttl_lookup(cache, key, now, fetch, ttl):
    if key not in cache:
        cache[key] = fetch(key)
    if cache[key] is not None:
        if cache[key]['expires_at'] > now:
            return cache[key]['value']
    cache[key] = fetch(key)
    cache[key]['expires_at'] = now + ttl
    return cache[key]['value']

