from collections import deque

def first_unique(values, count):
    if not values or not count:
        return []
    seen = set()
    queue = deque()
    for value in values:
        if value not in seen:
            queue.append(value)
            seen.add(value)
        if len(queue) > count:
            queue.popleft()
    return list(queue)

