def encode_frame(payload):
    if len(payload) > 65535:
        raise ValueError("payload length cannot exceed 65535")
    return pack(">H", len(payload)) + payload

from datetime import datetime

def wait_microseconds(start, end):
    if not (isinstance(start, datetime) and isinstance(end, datetime)):
        raise ValueError("Both arguments must be datetime objects")
    if start > end:
        raise ValueError("start must be less than or equal to end")
    if start.tzinfo is not None and end.tzinfo is not None and start.tzinfo != end.tzinfo:
        raise ValueError("start and end must have the same timezone")
    if start.tzinfo is not None:
        start = start.astimezone(end.tzinfo)
    delta = end - start
    if delta < datetime.min:
        raise ValueError("negative timedelta")
    if delta > datetime.max:
        raise ValueError("negative timedelta")
    return delta.microseconds

