import curses

def main(stdscr):
    stdscr.timeout(120)
    stdscr.keypad(True)
    height, width = stdscr.getmaxyx()
    stdscr.erase()
    stdscr.refresh()
    snake = [(height // 2, width // 2)]
    direction = (0, 0)
    while True:
        key = stdscr.getch()
        if key == ord("q"):
            break
        if key == ord("w") and (direction != (0, 1)):
            direction = (0, -1)
        elif key == ord("a") and (direction != (1, 0)):
            direction = (-1, 0)
        elif key == ord("s") and (direction != (0, -1)):
            direction = (0, 1)
        elif key == ord("d") and (direction != (-1, 0)):
            direction = (1, 0)
        snake = [(snake[0][0] + direction[0], snake[0][1] + direction[1])] + snake[:-1]
        if snake[0] == (height // 2, width // 2):
            score = 0
        elif snake[0] == (height - 1, width - 1) or snake[0] == (height - 1, 0) or snake[0] == (0, width - 1) or snake[0] == (0, 0):
            score = -1
        else:
            score = 1
        if score == -1:
            stdscr.erase()
            stdscr.addnstr(0, 0, "Game Over")
            stdscr.refresh()
            break
        elif score == 1:
            stdscr.erase()
            stdscr.addnstr(0, 0, "You Win")
            stdscr.refresh()
            break
        stdscr.erase()
        for row in range(height):
            for col in range(width):
                if (row, col) == (height // 2, width // 2):
                    stdscr.addch(row, col, ord("O"))
                elif (row, col) == (height - 1, width - 1) or (row, col) == (height - 1, 0) or (row, col) == (0, width - 1) or (row, col) == (0, 0):
                    stdscr.addch(row, col, ord("#"))
                elif (row, col) in snake:
                    stdscr.addch(row, col, ord("X"))
                else:
                    stdscr.addch(row, col, ord(" "))
        stdscr.refresh()
        stdscr.timeout(120)

if __name__ == "__main__":
    curses.wrapper(main)
